import {
  existsSync,
  mkdtempSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { runCommand } from "@/lib/execution/command-runner";
import type { GitHubRepository } from "@/lib/repository/github-repository";

export interface IngestedRepository {
  repository: GitHubRepository;
  repositoryPath: string;
  cleanup: () => void;
}

export async function ingestGitHubRepository(
  repository: GitHubRepository
): Promise<IngestedRepository> {
  const temporaryRoot = mkdtempSync(
    join(tmpdir(), "deployguard-repo-")
  );

  const repositoryPath = join(
    temporaryRoot,
    "repository"
  );

  try {
    const result = await runCommand(
      "git",
      [
        "clone",
        "--depth",
        "1",
        "--no-tags",
        repository.cloneUrl,
        repositoryPath,
      ],
      temporaryRoot
    );

    if (
      result.status !== "passed" ||
      !existsSync(repositoryPath)
    ) {
      throw new Error(
        result.stderr ||
          result.stdout ||
          "Repository clone failed."
      );
    }

    return {
      repository,
      repositoryPath,

      cleanup() {
        rmSync(temporaryRoot, {
          recursive: true,
          force: true,
        });
      },
    };
  } catch (error) {
    rmSync(temporaryRoot, {
      recursive: true,
      force: true,
    });

    throw error;
  }
}